 if (typeof user !== "object" || user === null)
 throw new TypeError("Expected user to be an object");
 if (typeof user.id !== "number")
 throw new TypeError("Expected user.id to be a number");
 if (typeof user.name !== "string")
 throw new TypeError("Expected user.name to be a string");
 return `hello ${user.name}`;
}
```

```typescript
import { Container } from '@di-framework/core/decorators';
import { useContainer } from '@di-framework/core/container';
import {
 Configuration,
 Value,
 envSource,
} from '@di-framework/config';

@Configuration({
 sources: [envSource({ prefix: 'APP_' })],
})
class AppConfig {
 host = 'localhost';
 port = 3000;
 database = { host: 'localhost', port: 5432 };
}

@Container()
class DatabaseService {
 @Value('database.host')
 host!: string;

 constructor(@Value('port') public port: number) {}
}

const db = useContainer().resolve(DatabaseService);
```

With `APP_PORT=8080` and `APP_DATABASE__HOST=db.internal`, `db.port` is `8080` and `db.host` is `db.internal`.

`@Configuration` builds defaults from class property initializers, merges sources, registers the result under the `'config'` token (with flattened paths), and registers the class as a singleton holding the loaded snapshot.

Prefer this when sources are async or you want explicit control in bootstrap code:

```typescript
import {
 loadAndRegisterConfig,
 envSource,
 objectSource,
 jsonFileSource,
 yamlFileSource,
 tomlFileSource,
} from '@di-framework/config';
import { useContainer } from '@di-framework/core/container';

const config = await loadAndRegisterConfig({
 defaults: { port: 3000 },
 sources: [
 yamlFileSource('./config.yaml', { optional: true }),
 tomlFileSource('./config.toml', { optional: true }),
 jsonFileSource('./config.json', { optional: true }),
 envSource({ prefix: 'APP_' }),
 objectSource({ /* test overrides */ }),
 ],
 token: 'config', // default
 flatten: true, // default — registers config.port, config.db.host, …
});

useContainer().resolve<number>('config.port');
```

Sync variants: `loadConfigSync` / `loadAndRegisterConfigSync` (all sources must return plain objects, not Promises).

```typescript
import { z } from 'zod';
import { loadConfigSync, objectSource } from '@di-framework/config';
import { zodSchema } from '@di-framework/config/zod';

const schema = zodSchema(
 z.object({
 port: z.coerce.number().default(3000),
 apiKey: z.string().min(1),
 }),
);

const config = loadConfigSync({
 sources: [objectSource({ apiKey: 'k', port: '4000' })],
 schema,
});
```

Any object with a `parse(input)` method can implement `ConfigSchema`. Use `schemaFromParse` to wrap a plain function.

With `flatten: true` (the default), every dotted path is a DI token. `@Value('database.host')` is equivalent to `@Component('config.database.host')`.

```typescript
@Container()
class ApiClient {
 constructor(
 @Value('apiKey') private apiKey: string,
 @Component('config') private config: AppConfig,
 ) {}
}
```

When a profile is selected, each file source loads the base file, then deep-merges `{profile}.config.{ext}` from the **same directory**. The overlay name is always `{profile}.config.{ext}` — it does not depend on the base file stem.

| Base file | Selected profile | Overlay |
| --- | --- | --- |
| `./config.yaml` | `dev` | `./dev.config.yaml` |
| `./config.toml` | `prod` | `./prod.config.toml` |
| `./settings.json` | `qa` | `./qa.config.json` |

Select profiles with, in order of precedence for a given source:

1. `yamlFileSource(path, { profiles: ['dev'] })` (and the JSON/TOML equivalents)
2. `@WithProfile('dev')` on the `@Configuration` class, or `loadConfig({ profiles: ['dev'] })`
3. `setSelectedProfiles('dev')`

```typescript
import { Configuration, WithProfile, yamlFileSource } from '@di-framework/config';

@WithProfile('dev')
@Configuration({
 sources: [yamlFileSource('./config.yaml')],
})
class AppConfig {
 host = 'localhost';
}
```

Several profiles merge left → right (`@WithProfile('dev', 'local')` applies `dev.config.yaml` then `local.config.yaml`). Missing overlay files are skipped; invalid names (`..`, path separators, empty) throw. `optional` on the source applies only to the base file.

```typescript
import { registerAuth } from '@di-framework/auth';
import { requireAuth, withAuthErrors, withAuthRoutes } from '@di-framework/auth/http';
import { TypedRouter, json } from '@di-framework/http';

const auth = registerAuth({
 // At least 32 bytes. HKDF-expanded into the CSRF and cookie keys.
 secret: process.env.AUTH_SECRET!,
 jwt: { issuer: 'https://api.example.com', audience: 'api' },
});

await auth.passwords.createUser({
 identifier: 'ada@example.com',
 password: 'correct horse battery staple',
});

const router = TypedRouter({ catch: withAuthErrors() });
const secure = withAuthRoutes(router);

router.get('/health', () => json({ ok: true }));

// `req.principal` is typed as Principal, not any.
secure.get('/me', (req) => json({ sub: req.principal.sub }));
```

An `AuthStrategy` answers one question: does this request carry a credential of my kind, and is it valid? Strategies are factory functions returning object literals, the same shape `@di-framework/events` uses for transports.

```typescript
import { authenticated, authFailed, chain, createPrincipal, noCredential } from '@di-framework/auth';

function headerStrategy(users: UserStore): AuthStrategy {
 return {
 name: 'x-user',
 async authenticate({ request }) {
 const id = request.headers.get('x-user-id');
 if (!id) return noCredential(); // not mine — try the next
 const user = await users.findById(id);
 if (!user) return authFailed('invalid_credentials', `No user '${id}'`); // mine, and bad — stop
 return authenticated(createPrincipal({ sub: user.id, method: 'api-key' }));
 },
 };
}

const strategy = chain([sessionStrategy, bearerStrategy, headerStrategy(users)]);
```

The three-state result is deliberate. `no-credential` means try the next strategy; `failed` halts the chain. Without that distinction, a forged bearer token falls through and the request ends up anonymous rather than rejected.

```typescript
interface Principal {
 sub: string; // stable subject id
 method: AuthMethod; // how they proved it on this request
 amr?: readonly string[]; // RFC 8176 methods, e.g. ['hwk', 'user', 'mfa']
 acr?: string;
 authTime: number; // when the original authentication happened
 scope?: readonly string[];
 sessionId?: string;
 claims?: Record<string, unknown>;
}
```

`AuthorizationManager` is the policy decision point; it does not impose a role or permission model. It receives the authenticated `Principal` and a transport context containing application-defined metadata. For policies that explicitly allow anonymous evaluation, the principal can be `undefined`.

The following example adapts an Open Policy Agent endpoint. The same interface can wrap SpiceDB, SQL, or an in-process policy engine.

```typescript
import {
 type AuthorizationManager,
 authorizationAllowed,
 authorizationDenied,
 registerAuth,
} from '@di-framework/auth';

const authorization: AuthorizationManager = {
 async authorize(principal, context) {
 const response = await fetch('https://opa.example.com/v1/data/library/allow', {
 method: 'POST',
 headers: { 'content-type': 'application/json' },
 body: JSON.stringify({
 input: {
 principal: principal ? { sub: principal.sub, scope: principal.scope } : null,
 metadata: context.metadata,
 transport: context.transport,
 },
 }),
 });

 if (!response.ok) {
 return authorizationDenied(`Policy agent returned HTTP ${response.status}`);
 }

 const decision = await response.json() as { result?: unknown };
 return decision.result === true
 ? authorizationAllowed()
 : authorizationDenied('Policy agent returned a non-allow decision');
 },
};

registerAuth({ secret, authorization });
```

Denial reasons are retained for application logging but are never exposed to clients. Unless a guard supplies its own `manager`, HTTP and GraphQL resolve the manager registered under `auth.AuthorizationManager` by `registerAuth`.

```typescript
import { TypedRouter, json } from '@di-framework/http';
import {
 applyAuthHeaders, createAuthRoutes, mountAuthRoutes,
 requireAuth, requireAuthz, secured, securitySchemesFor, withAuthErrors, withAuthRoutes,
} from '@di-framework/auth/http';

const router = TypedRouter({
 before: [requireAuth()], // or guard per route, below
 catch: withAuthErrors(),
 finally: [applyAuthHeaders], // applies cookies a guard queued
});
```

Per-route protection, which types the principal:

```typescript
const secure = withAuthRoutes(router);

@Controller()
export class MeController {
 @Endpoint({ summary: 'Current principal', security: secured('bearerAuth') })
 static get = secure.get('/me', async (req) => {
 const controller = useContainer().resolve(MeController);
 return json(await controller.load(req.principal.sub));
 });
}
```

Escape hatches: `{ auth: false }` for a public route, `{ auth: { mode: 'optional' } }` to attach a principal when present.

Add authorization metadata to a protected route. Authentication runs first, then the registered manager decides whether the principal may perform the action:

```typescript
secure.get('/admin', (req) => json({ subject: req.principal.sub }), {
 authorization: { metadata: { resource: 'admin', action: 'read' } },
});
```

When composing route middleware directly, keep the same order:

```typescript
router.get('/admin', handler, {
 use: [requireAuth(), requireAuthz({ metadata: { action: 'admin:read' } })],
});
```

By default, `requireAuthz()` returns 401 when no principal is present. Set `allowAnonymous: true` only for a manager that intentionally evaluates public-policy requests. A policy denial produces a generic 403 response with the `access_denied` code; its internal reason stays redacted.

```typescript
const spec = generateOpenAPI({
 title: 'API',
 securitySchemes: securitySchemesFor([auth.strategy]),
 security: secured('bearerAuth'), // document-level default
});
```

Mark an operation public with `@Endpoint({ security: publicEndpoint })`.

```typescript
import { buildSemanticSchema, createGraphQLHandler } from '@di-framework/graphql';
import { Authenticated, Authorize, createAuthContext, protectSchema, requireSubject } from '@di-framework/auth/graphql';

@Portal()
class Library {
 @Field(() => Book)
 catalogue(): Book[] { return books; } // public

 @Authenticated()
 @Authorize({ resource: 'loan', action: 'create' })
 @Action(() => Loan)
 borrow(@Arg('id') id: string, @Ctx() ctx: AuthGraphQLContext): Loan {
 return lend(id, requireSubject(ctx));
 }
}

const api = protectSchema(buildSemanticSchema());
const handler = createGraphQLHandler(api, {
 context: createAuthContext({ strategy: auth.strategy }),
});
```

`@Authenticated({ amr: ['mfa'], maxAge: 300 })` requires a stronger or more recent authentication — still authentication, not authorization.

`@Authorize(metadata)` applies to types, fields, actions, and subscriptions. It calls the manager after any `@Authenticated()` check. Use `@Authorize(metadata, { allowAnonymous: true })` only for deliberately anonymous policies. A denial uses `errors[0].extensions.code === 'FORBIDDEN'`, while the manager's reason remains private.

`@PublicField()` is a complete public opt-out: it disables both authentication and authorization declarations for that field, including rules inherited from the containing type.

Authentication rejections surface as `errors[0].extensions.code === 'UNAUTHENTICATED'`, and the message on the wire is always the generic public text.

Note: `printSDL` renders from the type graph rather than the executable schema, so `@authenticated` does not appear in the printed SDL. The SDL describes the shape; the executable schema enforces access.

```typescript
import { inMemoryAuthStores } from '@di-framework/auth';
import { repoSessionStore, repoUserStore } from '@di-framework/auth/repo';

registerAuth({
 secret,
 stores: {
 users: repoUserStore({ adapter: userAdapter }),
 sessions: repoSessionStore({ adapter: sessionAdapter }),
 },
});
```

Interfaces: `UserStore`, `SessionStore`, `CredentialStore`, `StateStore`, `RefreshTokenStore`, `KeyStore`, `LoginThrottle`.

Three methods must be a compare-and-swap: `StateStore.consume`, `RefreshTokenStore.rotate`, and `CredentialStore.updateSignCount`. They are the replay defences for OAuth `state`, refresh tokens, and WebAuthn sign counters. `StorageAdapter` has no conditional write, so `repoStateStore` and `repoRefreshTokenStore` require an explicit `atomic` hook and **throw at construction without one** rather than shipping a defence that silently does nothing.

`@di-framework/auth/server` turns an application into an OAuth 2.0 (RFC 6749) and OpenID Connect 1.0 Authorization Server:

```typescript
import { AuthorizationServer, handleOAuthServerRequest } from '@di-framework/auth/server';

const server = new AuthorizationServer({
 issuer: 'https://auth.example.com',
 clients: clientStore,
 codes: authCodeStore,
 tokens: oauthTokenStore,
 keyService,
});

// Serve OAuth 2.0 & OIDC routes:
// /.well-known/openid-configuration, /.well-known/jwks.json, /oauth/authorize, /oauth/token, /oauth/revoke, /oauth/userinfo
const response = await handleOAuthServerRequest(server, request);
```

- **PKCE Requirement**: Mandatory `code_challenge_method=S256` (RFC 7636).
- **Exact Redirect URI Matching**: String equality check preventing wildcard/substring redirect hijacks.
- **Revocation Endpoint**: RFC 7009 token revocation support (`/oauth/revoke`).
- **OIDC Core 1.0**: Issuer discovery metadata, JWKS endpoint, signed ID Tokens, and UserInfo endpoint.

```typescript
import { Component, Container } from '@di-framework/core/decorators';
import {
 Arg,
 Field,
 ID,
 Portal,
 SemanticType,
 buildSemanticSchema,
 createGraphQLHandler,
} from '@di-framework/graphql';

interface BookRow {
 id: string;
 title: string;
 author: string;
}

@Container()
class BookRepository {
 private rows: BookRow[] = [{ id: 'b1', title: 'Ariel', author: 'Sylvia Plath' }];

 find(id: string) {
 return this.rows.find((row) => row.id === id) ?? null;
 }
}

@SemanticType({ key: 'id', expose: { title: () => String, author: () => String } })
class Book {
 constructor(
 public id: string,
 public title: string,
 public author: string,
 ) {}

 @Field(() => String)
 shelfLabel(): string {
 return `${this.author.split(' ').pop()}-${this.id}`.toUpperCase();
 }
}

@Portal()
class CatalogPortal {
 constructor(@Component(BookRepository) private repo: BookRepository) {}

 @Field(() => Book, { nullable: true })
 book(@Arg('id', () => ID) id: string) {
 return this.repo.find(id);
 }
}

const api = buildSemanticSchema();

const result = await api.execute({
 query: '{ book(id: "b1") { title shelfLabel } }',
});
// { data: { book: { title: 'Ariel', shelfLabel: 'PLATH-B1' } } }

const handler = createGraphQLHandler(api);
```

`api.sdl` is the schema as SDL, `api.schema` is an executable `graphql-js` schema, and `api.graph` is the resolved semantic graph you can assert against.

`@SemanticType` declares a class as a type in the schema. Use `expose` for constructor parameter properties (which cannot carry their own decorators). A type with a `key` always exposes it; `boundary: true` requires a `key` so other contexts can re-identify the object.

```typescript
@SemanticType({
 key: 'id',
 boundary: true,
 expose: {
 title: () => String,
 copies: { type: () => Int, description: 'Copies owned.' },
 },
})
class Book {
 constructor(
 public id: string,
 public title: string,
 public copies: number,
 ) {}
}
```

A portal is a root object registered with the DI container:

- `@Field` → Query fields
- `@Action` → Mutation fields
- `@Subscription` → Subscription fields

```typescript
@Portal({ singleton: true })
class CatalogPortal {
 constructor(@Component(BookRepository) private repo: BookRepository) {}

 @Field(() => [Book])
 books(@Arg('limit', () => Int, { nullable: true, defaultValue: 10 }) limit: number) {
 return this.repo.findAll(limit);
 }

 @Action(() => Book)
 addBook(@Arg('input', () => BookInput) input: BookInput) {
 return this.repo.create(input);
 }
}
```

Portals cannot be used as field types. If no portal declares a query field, the schema synthesizes `_contexts: [String!]!` so it stays valid.

An `@Action` on a semantic type (not a portal) becomes a root mutation named `<type><Method>`, with an implicit key argument. The entity is loaded through `@Lookup` before the method runs.

```typescript
@SemanticType({ boundary: true, key: 'id' })
class Loan {
 @Lookup()
 static load(id: string) {
 return useContainer().resolve(LoanService).find(id);
 }

 @Action({ description: 'Give the book back.' })
 checkIn(): void {
 if (this.state !== 'Active') throw new Error(`Loan ${this.id} was already returned.`);
 this.state = 'Returned';
 }
}
```

That yields `loanCheckIn(id: ID!): Loan!`.

`@BoundedContext('Name')` records who owns a class. By default (`enforceBoundaries: true`) a context may only reference or extend another context's types when those types declare `boundary: true` — otherwise `SemanticBoundaryError` is thrown at build time.

```typescript
@BoundedContext('Reviews')
@SemanticType() // internal; no other context may point at it
class Review {
 /* … */
}
```

Build a subset of contexts for a deployment seam:

```typescript
const publicApi = buildSemanticSchema({ contexts: ['Catalog', 'Reviews'] });
```

`@Extends` contributes fields to a boundary type owned elsewhere. The extension class is DI-managed and receives the parent through `@Parent()`.

```typescript
@BoundedContext('Reviews')
@Extends(() => Book)
class BookReviews {
 constructor(@Component(ReviewRepository) private repo: ReviewRepository) {}

 @Field(() => [Review], { batch: 'reviewsForBooks' })
 reviews(@Parent() book: BookRow) {
 return this.repo.forBook(book.id);
 }

 reviewsForBooks(books: BookRow[]) {
 return this.repo.forBooks(books.map((book) => book.id));
 }
}
```

`@InputType` classes are rebuilt from the plain values GraphQL hands the resolver, so their methods are callable. An input type must declare at least one `@Field`.

```typescript
@InputType()
class ReviewInput {
 @Field(() => Int) rating!: number;

 clampedRating() {
 return Math.min(5, Math.max(1, this.rating));
 }
}
```

`@Subscription` reads the container's event bus (what core `@Publisher` writes to). Subscriptions may only be declared on portals.

```typescript
@Container()
class LoanService {
 @Publisher('loan.checkedOut')
 checkOut(bookId: string, memberId: string): LoanRow {
 /* … */
 }
}

@Portal()
class LendingPortal {
 @Subscription('loan.checkedOut', () => Loan, {
 filter: (payload, args) => !args.memberId || payload?.result?.memberId === args.memberId,
 })
 loanCheckedOut(
 @Parent() loan: LoanRow,
 @Arg('memberId', () => ID, { nullable: true }) memberId: string | null,
 ) {
 return loan;
 }
}
```

Use `api.subscribe(...)` to get an `AsyncIterableIterator` of results.

Types are runtime markers — no `reflect-metadata`:

```typescript
import { Bool, DateTime, Float, ID, Int, Json, Str, registerEnum } from '@di-framework/graphql';

export const Genre = { Fiction: 'Fiction', Poetry: 'Poetry' } as const;
registerEnum(Genre, { name: 'Genre' });

@Field(() => ID) id!: string;
@Field(() => [Book]) books!: Book[];
@Field(() => Genre) genre!: string;
```

`String`, `Number`, `Boolean`, and `Date` also work and map to `String`, `Float`, `Boolean`, and `DateTime`.

```typescript
const api = buildSemanticSchema({
 container, // defaults to useContainer()
 registry, // defaults to the global SemanticRegistry
 contexts: ['Catalog'], // restrict to these bounded contexts
 enforceBoundaries: true,
 strictTypes: false, // reject undeclared types instead of assuming String
 print: { directives: true, descriptions: true },
});
```

| Member | Purpose |
| --- | --- |
| `graph` | Resolved, validated semantic graph |
| `schema` | Executable `graphql-js` schema |
| `sdl` | Same graph as SDL |
| `execute({ query, variables, operationName, context })` | Run a query/mutation |
| `subscribe({ … })` | Async iterable of subscription results |

```typescript
import { createGraphQLHandler } from '@di-framework/graphql';

export const handler = createGraphQLHandler(api, {
 context: (request) => ({ memberId: request.headers.get('x-member-id') }),
});

Bun.serve({ port: 4000, fetch: handler });
```

`GET` reads `query` / `variables` / `operationName` from the query string, `POST` from a JSON body. Subscriptions need a connection — drive `api.subscribe()` from a WebSocket or SSE endpoint. Prefer `createGraphqlTransportWs` from `@di-framework/socket/graphql` (see Sockets); the GraphQL example uses this helper.

`@di-framework/graphql/core` never imports `graphql`, so emitting the schema is cheap enough for CI:

```typescript
import { buildTypeGraph, printSDL } from '@di-framework/graphql/core';

const graph = buildTypeGraph({ strictTypes: true });
await Bun.write('schema.graphql', printSDL(graph, { directives: true }));
```

With `directives: true`, ownership is recorded (`@key`, `@context`), which makes the artifact worth diffing in review. `buildTypeGraph()` also throws if a context has reached somewhere it should not.

`contexts: [...]` slices a schema. What makes a slice *deployable* is that it still resolves references across the seam — through boundary stubs:

```typescript
const subgraphs = buildSemanticSubgraphs({ federation: true });
// { Catalog: SemanticSchema, Lending: SemanticSchema }

Bun.serve({ port: 4001, fetch: createGraphQLHandler(subgraphs.Catalog) });
```

For SDL artifacts, `buildContextSubgraphs()` does the same on the `graphql`-free path:

```typescript
import { buildContextSubgraphs, printSDL } from '@di-framework/graphql/core';

for (const [context, graph] of Object.entries(buildContextSubgraphs())) {
 await Bun.write(`${context}.graphql`, printSDL(graph, { federation: true }));
}
```

The framework automatically detects circular dependencies and throws an error:

```typescript
// This will be detected and throw an error:
@Container()
class ServiceA {
 constructor(@Component(ServiceB) private b: ServiceB) {}
}

@Container()
class ServiceB {
 constructor(@Component(ServiceA) private a: ServiceA) {}
}

// Attempting to resolve either service will throw:
// Error: Circular dependency detected while resolving ServiceA
```

**How to fix:**

1. **Refactor to remove the circular dependency** - Extract common logic to a third service
2. **Use property injection** - Delay dependency resolution
3. **Rethink your architecture** - Circular dependencies often indicate a design issue

**Example refactoring:**

```typescript
// Before (circular):
@Container()
class ServiceA {
 constructor(@Component(ServiceB) private b: ServiceB) {}
}

@Container()
class ServiceB {
 constructor(@Component(ServiceA) private a: ServiceA) {}
}

// After (refactored):
@Container()
class SharedService {
 // Common logic extracted here
}

@Container()
class ServiceA {
 constructor(@Component(SharedService) private shared: SharedService) {}
}

@Container()
class ServiceB {
 constructor(@Component(SharedService) private shared: SharedService) {}
}
```

Attempting to resolve or inject a service that hasn't been registered will throw an error:

```typescript
@Container()
class MyService {
 constructor(@Component(UnregisteredService) private s: UnregisteredService) {}
}

// Error: Service 'UnregisteredService' is not registered in the DI container
```

**How to fix:**

1. **Register the service** - Add `@Container()` decorator to the service class
2. **Check your imports** - Ensure the service file is imported somewhere in your application
3. **For factory services** - Ensure `registerFactory()` was called before resolution

**Example fix:**

```typescript
// Add the @Container() decorator
@Container()
export class UnregisteredService {
 // Service implementation
}

// Or register manually
container.register(UnregisteredService);

// Or register as factory
container.registerFactory('serviceName', () => new UnregisteredService());
```

If decorators aren't working, check your TypeScript/SWC configuration:

```typescript
// This won't work without proper configuration
@Container()
class MyService {
 constructor(@Component(DatabaseService) private db: DatabaseService) {}
}

// Error: Cannot read properties of undefined (reading 'db')
```

**How to fix:**

Ensure your `../../../tsconfig.json` has:

```json
{
 "compilerOptions": {
 "experimentalDecorators": true,
 "emitDecoratorMetadata": true
 }
}
```

Or for SWC (`.swcrc`):

```json
{
 "jsc": {
 "parser": {
 "decorators": true
 },
 "transform": {
 "legacyDecorator": true,
 "decoratorMetadata": true
 }
 }
}
```

Use `container.has()` to check if a service is registered:

```typescript
if (container.has(UserService)) {
 const service = container.resolve(UserService);
} else {
 console.warn('UserService not registered');
}
```

Create a startup validation routine:

```typescript
@Container()
export class StartupValidator {
 validateServices() {
 const requiredServices = [DatabaseService, AuthService, CacheService, LoggerService];

 const missing = requiredServices.filter((service) => !container.has(service));

 if (missing.length > 0) {
 throw new Error(`Missing required services: ${missing.map((s) => s.name).join(', ')}`);
 }
 }
}

// Run at application startup
const validator = container.resolve(StartupValidator);
validator.validateServices();
```

List all registered services for debugging:

```typescript
const serviceNames = container.getServiceNames();
console.log('Registered services:', serviceNames);
```

Services may fail during initialization:

```typescript
@Container()
export class DatabaseService {
 constructor() {
 // This might throw
 this.connect();
 }

 private connect() {
 throw new Error('Connection failed');
 }
}

// Wrap resolution in try-catch
try {
 const db = container.resolve(DatabaseService);
} catch (error) {
 console.error('Failed to initialize DatabaseService:', error);
 // Handle error appropriately
}
```

Provide fallback implementations:

```typescript
// Try to use preferred service, fall back to alternative
let logger;
try {
 logger = container.resolve(ProductionLogger);
} catch (error) {
 console.warn('Production logger unavailable, using console');
 logger = container.resolve(ConsoleLogger);
}
```

Test error handling in your services:

```typescript
import { Container as DIContainer } from '@di-framework/core/container';

describe('ServiceA', () => {
 it('should handle missing dependencies gracefully', () => {
 const testContainer = new DIContainer();

 // Don't register required dependency
 testContainer.register(ServiceA);

 expect(() => {
 testContainer.resolve(ServiceA);
 }).toThrow("Service 'ServiceB' is not registered");
 });

 it('should detect circular dependencies', () => {
 const testContainer = new DIContainer();

 testContainer.register(ServiceA);
 testContainer.register(ServiceB);

 expect(() => {
 testContainer.resolve(ServiceA);
 }).toThrow('Circular dependency detected');
 });
});
```

By default, all services are singletons - the same instance is reused. For services that need a new instance each time, use `singleton: false`:

```typescript
import { useContainer } from '@di-framework/core/container';
const container = useContainer();

@Container({ singleton: false })
export class RequestContext {
 id = Math.random().toString();

 constructor(@Component(LoggerService) private logger: LoggerService) {
 this.logger.log(`Request context created: ${this.id}`);
 }
}

// Each resolve creates a new instance
const ctx1 = container.resolve(RequestContext); // new instance
const ctx2 = container.resolve(RequestContext); // different instance
console.log(ctx1.id !== ctx2.id); // true
```

**When to use transient services:**

- Request-scoped services
- Session-scoped services
- Services with mutable state that shouldn't be shared
- Services that need fresh data on each use

Register services using factory functions for complex initialization logic:

```typescript
import { useContainer } from '@di-framework/core/container';
const container = useContainer();

container.registerFactory(
 'apiClient',
 () => {
 return new HttpClient({
 baseUrl: process.env.API_URL,
 timeout: 5000,
 headers: {
 Authorization: `Bearer ${process.env.API_TOKEN}`,
 },
 });
 },
 { singleton: true },
);

// Use in services
@Container()
export class UserService {
 constructor(@Component('apiClient') private api: any) {}

 async getUser(id: string) {
 return this.api.get(`/users/${id}`);
 }
}
```

**Factory function benefits:**

- Initialize services with environment variables
- Create instances with complex configuration
- Conditionally create different implementations
- Integrate third-party libraries

```typescript
import { Repository, InMemoryRepository } from '@di-framework/repo';

@Repository()
export class UserRepository extends InMemoryRepository<User, number> {
 async findByEmail(email: string): Promise<User | null> {
 const all = await this.findAll();
 return all.find((u) => u.email === email) || null;
 }
}
```

```typescript
import { SoftDeleteRepository, SoftDeletable } from '@di-framework/repo';

interface Product extends SoftDeletable {
 id: string;
 name: string;
}

@Repository()
export class ProductRepository extends SoftDeleteRepository<Product, string> {
 // Implement required abstract methods for your adapter
}
```

See the Repositories documentation for more details.

Services can implement lifecycle methods for initialization and context management:

```typescript
import { useContainer } from '@di-framework/core/container';
const container = useContainer();

@Container()
export class DatabaseService {
 private connected = false;
 private dbUrl: string = '';

 setEnv(env: Record<string, any>) {
 // Called to initialize environment-specific config
 this.dbUrl = env.DATABASE_URL;
 console.log('DB URL configured:', this.dbUrl);
 }

 setCtx(context: any) {
 // Called to set execution context
 console.log('Context set:', context);
 }

 connect() {
 this.connected = true;
 console.log('Connected to:', this.dbUrl);
 }
}

// Usage
const db = container.resolve(DatabaseService);
db.setEnv(process.env);
db.setCtx({ userId: '123' });
db.connect();
```

Inject multiple dependencies using constructor parameters:

```typescript
@Container()
export class ApplicationContext {
 constructor(
 @Component(DatabaseService) private db: DatabaseService,
 @Component(LoggerService) private logger: LoggerService,
 @Component(AuthService) private auth: AuthService,
 @Component(CacheService) private cache: CacheService,
 @Component(EmailService) private email: EmailService,
 ) {}

 async initialize() {
 this.logger.log('Initializing application...');
 await this.db.connect();
 this.auth.setup();
 this.cache.connect();
 }
}
```

Use `@Publisher` to emit a custom event when a method is called. By default, it emits after the method executes successfully or fails.

```typescript
@Container()
export class UserService {
 @Publisher({ event: 'user.created', phase: 'after', logging: true })
 async createUser(dto: any) {
 // ...
 return { id: 1, ...dto };
 }
}
```

Use `@Subscriber` to automatically listen for custom events. Subscribed methods receive a payload containing the `className`, `methodName`, `args`, `startTime`, `endTime`, `result`, and `error`.

```typescript
@Container()
export class NotificationService {
 @Subscriber('user.created')
 onUserCreated(event: any) {
 if (event.result) {
 console.log(`Sending welcome email to ${event.result.name}`);
 }
 }
}
```

To publish those same events to Kafka or NATS (or consume remote topics back onto the bus), use `@di-framework/events`. For WebSocket, TCP, or UDP peers (including a secure channel and Cloudflare Workers / Durable Objects), use `@di-framework/socket`.

Use `@Telemetry` to track execution of any method in an injectable service. It automatically captures:

- Start and end times (duration)
- Method arguments
- Return value
- Errors (if the method throws)

```typescript
@Container()
export class ApiService {
 @Telemetry({ logging: true }) // Logs duration and status to console
 async fetchData(id: string) {
 const response = await fetch(`https://api.example.com/data/${id}`);
 return response.json();
 }
}
```

Use `@TelemetryListener` to create monitoring services that react to telemetry events from across your application:

```typescript
@Container()
export class MonitoringService {
 @TelemetryListener()
 onTelemetry(event: any) {
 const { className, methodName, startTime, endTime, error } = event;
 const duration = endTime - startTime;

 if (error) {
 console.error(`Alert: ${className}.${methodName} failed after ${duration}ms:`, error);
 } else {
 console.log(`Metric: ${className}.${methodName} took ${duration}ms`);
 }

 // Send to external monitoring service (e.g., Datadog, Sentry)
 metricsService.timing(`${className}.${methodName}`, duration);
 }
}
```

Create isolated containers for different parts of your application:

```typescript
import { Container as DIContainer } from '@di-framework/core/container';

// Create custom containers
const apiContainer = new DIContainer();
const workerContainer = new DIContainer();

// Register services in specific containers
@Container({ container: apiContainer })
export class ApiService {
 // Only available in apiContainer
}

@Container({ container: workerContainer })
export class WorkerService {
 // Only available in workerContainer
}

// Resolve from specific containers
const apiService = apiContainer.resolve(ApiService);
const workerService = workerContainer.resolve(WorkerService);
```

**Use cases for custom containers:**

- Multi-tenant applications
- Plugin systems
- Testing with isolated environments
- Microservices within a monorepo

Clone an existing container and optionally carry over singleton instances:

```typescript
import { useContainer } from '@di-framework/core/container';
const container = useContainer();

// Seed the base container
container.register(DatabaseService);
container.register(LoggerService);
const sharedDb = container.resolve(DatabaseService);

// Create an isolated fork for a tenant/request
const tenantContainer = container.fork({ carrySingletons: true });
tenantContainer.registerFactory('config', () => loadTenantConfig());

// Resolves share the DatabaseService instance but have their own registrations
const tenantCtx = tenantContainer.resolve(ApplicationContext);
```

**Why:** Quickly spin up scoped containers without re-registering every service. Carry over expensive singletons (DB connections) while keeping registrations isolated.

Use the observer hooks to add diagnostics or metrics around registration and resolution:

```typescript
import { useContainer } from '@di-framework/core/container';
const container = useContainer();

const stop = container.on('resolved', ({ key, singleton, fromCache }) => {
 const name = typeof key === 'string' ? key : key.name;
 metrics.increment('di.resolve', { name, singleton, fromCache });
});

// Later, if needed:
stop();
```

**Use cases:**

- Log or trace dependency graphs during debugging
- Emit metrics for cache hit/miss on singletons
- Enforce policies (e.g., warn on transient resolutions in hot paths)

Create fresh instances without registering them, and override constructor arguments for primitives or config:

```typescript
import { Component } from '@di-framework/core/decorators';
import { container } from '@di-framework/core/container';

class EmailService {
 constructor(
 @Component(LoggerService) private logger: LoggerService,
 private sender: string,
 ) {}
}

const emailer = container.construct(EmailService, {
 1: 'no-reply@example.com',
});
```

**Why:** Useful for ad-hoc utilities, one-off jobs, or tests where you need DI-managed dependencies plus specific literal parameters.

For typed, validated configuration from env, JSON, YAML, and TOML files, use `@di-framework/config`. A minimal imperative example:

```typescript
import { loadAndRegisterConfig, envSource } from '@di-framework/config';
import { Container, Component } from '@di-framework/core/decorators';

await loadAndRegisterConfig({
 defaults: {
 database: { host: 'localhost', port: 5432 },
 },
 sources: [envSource({ prefix: 'APP_' })],
});

@Container()
export class DatabaseService {
 constructor(@Component('config') private config: { database: { host: string } }) {
 console.log('DB Config:', this.config.database);
 }
}
```

You can still register a plain factory with `registerFactory('config', …)` when you do not need sources or validation.

Register different implementations based on environment:

```typescript
import { useContainer } from '@di-framework/core/container';
const container = useContainer();

// Register different implementations
if (process.env.NODE_ENV === 'production') {
 container.registerFactory('logger', () => new ProductionLogger(), {
 singleton: true,
 });
} else {
 container.registerFactory('logger', () => new DevelopmentLogger(), {
 singleton: true,
 });
}

// Services get the right implementation
@Container()
export class UserService {
 constructor(@Component('logger') private logger: any) {
 this.logger.log('UserService initialized');
 }
}
```

Compose complex services from simpler ones:

```typescript
@Container()
export class DataAccessLayer {
 constructor(
 @Component(DatabaseService) private db: DatabaseService,
 @Component(CacheService) private cache: CacheService,
 ) {}

 async get(key: string) {
 // Try cache first
 const cached = await this.cache.get(key);
 if (cached) return cached;

 // Fall back to database
 const data = await this.db.query(`SELECT * FROM data WHERE key = '${key}'`);
 await this.cache.set(key, data);
 return data;
 }
}

@Container()
export class BusinessLogicLayer {
 constructor(
 @Component(DataAccessLayer) private dal: DataAccessLayer,
 @Component(ValidationService) private validator: ValidationService,
 ) {}

 async processRequest(request: any) {
 this.validator.validate(request);
 return this.dal.get(request.key);
 }
}
```

