```typescript
import { Container, Publisher, Subscriber } from '@di-framework/core/decorators';
import { useContainer } from '@di-framework/core/container';
import {
 createEventBridge,
 memoryTransport,
} from '@di-framework/events';

@Container()
class OrderService {
 @Publisher('order.placed')
 place(id: string) {
 return { id };
 }
}

@Container()
class FulfillmentService {
 @Subscriber('order.placed')
 onPlaced(payload: unknown) {
 const envelope = payload as { result?: { id: string } };
 console.log('order', envelope.result ?? payload);
 }
}

const transport = memoryTransport();
const bridge = createEventBridge({
 transport,
 routes: {
 outbound: [{ event: 'order.placed', topic: 'orders' }],
 inbound: [{ topic: 'payments', event: 'payment.captured' }],
 },
});

await bridge.start();

const orders = useContainer().resolve(OrderService);
useContainer().resolve(FulfillmentService);
orders.place('o1'); // local subscriber + outbound publish to "orders"

await bridge.stop();
```

Outbound payloads default to unwrapping the `@Publisher` envelope (`result`), matching GraphQL subscriptions. Inbound emits the decoded payload as-is.

```typescript
import { useContainer } from '@di-framework/core/container';
import { EventBridge, Outbound, Inbound, memoryTransport } from '@di-framework/events';

@EventBridge({ transport: () => memoryTransport() })
class OrderEvents {
 @Outbound('order.placed', {
 topic: 'orders',
 key: (p: unknown) => {
 if (p && typeof p === 'object' && 'result' in p) {
 return (p as { result?: { id?: string } }).result?.id;
 }
 return undefined;
 },
 })
 outboundOrders!: undefined;

 @Inbound({ topic: 'payments.captured', event: 'payment.captured' })
 inboundPayments!: undefined;
}

// autoStart (default) starts the bridge on resolve:
useContainer().resolve(OrderEvents);

// or disable autoStart and call:
// await startEventBridges();
```

Inject a shared transport instead of passing one in options:

```typescript
import { useContainer } from '@di-framework/core/container';

const container = useContainer();
container.registerFactory('EventTransport', () => memoryTransport(), { singleton: true });

@EventBridge() // resolves token "EventTransport"
class OrderEvents { /* ... */ }
```

```typescript
import { createEventBridge } from '@di-framework/events';
import { kafkaTransport } from '@di-framework/events/kafka';

const transport = kafkaTransport({
 client: { clientId: 'my-app', brokers: ['localhost:9092'] },
 groupId: 'my-app-consumers',
});

const bridge = createEventBridge({
 transport,
 routes: {
 outbound: [{ event: 'order.placed', topic: 'orders' }],
 inbound: [{ topic: 'orders', event: 'order.placed' }],
 },
});
await bridge.start();
```

Topic creation is left to operators. Delivery is at-least-once via the consumer group.

```typescript
import { natsTransport } from '@di-framework/events/nats';

const transport = natsTransport({
 servers: 'nats://127.0.0.1:4222',
 // jetstream: true,
 // durable: 'my-consumer',
});
```

Core NATS is the default. Set `jetstream: true` (and usually `durable`) for durable consumers.

Marks a class as injectable and automatically registers it with the DI container.

**Options:**

- `singleton?: boolean` (default: `true`) - Create a new instance each time or reuse the same instance
- `container?: DIContainer` - Specify a custom container (defaults to global container)

**Note:** Import as `import { Container as DIContainer } from '@di-framework/core/container'` to avoid name collision with the `@Container` decorator.

**Example:**

```typescript
import { Container } from '@di-framework/core/decorators';

// Singleton service (default)
@Container()
export class DatabaseService {
 connect() {
 console.log('Connected');
 }
}

// Non-singleton service
@Container({ singleton: false })
export class RequestScopedService {
 // New instance created for each resolution
}

// Custom container
import { Container as DIContainer } from '@di-framework/core/container';
const customContainer = new DIContainer();

@Container({ container: customContainer })
export class CustomService {
 // Registered in custom container
}
```

Marks a constructor parameter or property for dependency injection.

**Parameters:**

- `target` - The class to inject or a string identifier for factory-registered services

**Example - Constructor Parameter:**

```typescript
@Container()
export class OrderService {
 constructor(@Component(DatabaseService) private db: DatabaseService) {}
}
```

**Example - Property Injection:**

```typescript
@Container()
export class ReportService {
 @Component(DatabaseService)
 private db!: DatabaseService;
}
```

**Example - Factory Service:**

```typescript
@Container()
export class UserService {
 constructor(@Component('config') private config: any) {}
}
```

Marks a method for telemetry tracking. When called, it emits a `telemetry` event on the container. Works with both synchronous and asynchronous methods.

**Options:**

- `logging?: boolean` (default: `false`) - If true, logs the method execution details (status and duration) to the console.

**Example:**

```typescript
@Container()
export class ApiService {
 @Telemetry({ logging: true })
 async fetchData(id: string) {
 // ...
 }
}
```

Marks a method as a listener for telemetry events. The method will be automatically registered to the container's `telemetry` event when the service is instantiated.

**Example:**

```typescript
@Container()
export class MonitoringService {
 @TelemetryListener()
 onTelemetry(event: any) {
 console.log(
 `Method ${event.className}.${event.methodName} took ${event.endTime - event.startTime}ms`,
 );
 }
}
```

Marks a method to publish a custom event on the container upon invocation. This is useful for cross-platform event-driven architectures.

**Parameters:**

- `optionsOrEvent` - A string representing the event name, or an options object.

**Options:**

- `event: string` - The custom event name.
- `phase?: "before" | "after" | "both"` (default: `"after"`) - When to emit the event relative to method invocation.
- `logging?: boolean` (default: `false`) - Optional console logging for debug purposes.

**Example:**

```typescript
@Container()
export class UserService {
 @Publisher('user.created')
 createUser(name: string) {
 return { id: 1, name };
 }
}
```

Marks a method to subscribe to a custom event emitted on the container. The decorated method will automatically receive the published payload when the event occurs.

**Parameters:**

- `event: string` - The custom event name to listen for.

**Example:**

```typescript
@Container()
export class AuditService {
 @Subscriber('user.created')
 onUserCreated(event: any) {
 console.log('User created:', event.result);
 }
}
```

Register a service using a factory function.

**Parameters:**

- `name: string` - Identifier for the service
- `factory: () => T` - Factory function that creates the service instance
- `options?` - Registration options
 - `singleton?: boolean` (default: `true`)

**Example:**

```typescript
container.registerFactory(
 'config',
 () => ({
 apiKey: process.env.API_KEY,
 dbUrl: process.env.DATABASE_URL,
 }),
 { singleton: true },
);

// Use in services
@Container()
export class UserService {
 constructor(@Component('config') private config: any) {}
}
```

Resolve and get an instance of a service.

**Parameters:**

- `serviceClass` - The class or string identifier to resolve

**Returns:** Instance of the service with all dependencies injected

**Example:**

```typescript
// By class
const userService = container.resolve<UserService>(UserService);

// By name (for factory-registered services)
const config = container.resolve('config');
```

Check if a service is registered in the container.

**Parameters:**

- `serviceClass` - The class or string identifier to check

**Returns:** `boolean`

**Example:**

```typescript
if (container.has(UserService)) {
 const service = container.resolve(UserService);
}
```

Subscribe to container lifecycle events (observer pattern). Returns an unsubscribe function from `on`.

**Events:**

- `registered` - `{ key, singleton, kind }`
- `resolved` - `{ key, instance, singleton, fromCache }`
- `constructed` - `{ key, instance, overrides }`
- `cleared` - `{ count }`
- `telemetry` - `{ className, methodName, args, startTime, endTime, result, error }`

**Example:**

```typescript
const stop = container.on('resolved', ({ key, fromCache }) => {
 const name = typeof key === 'string' ? key : key.name;
 console.log(`Resolved ${name} (from cache: ${fromCache})`);
});

// Later, to unsubscribe
stop();
```

Create a fresh instance without registering it, while still resolving dependencies. Use `overrides` to supply specific constructor arguments (by index) such as primitives or config values.

**Example:**

```typescript
import { Component } from '@di-framework/core/decorators';
import { container } from '@di-framework/core/container';

class LoggerService {
 log(message: string) {
 console.log(message);
 }
}

class Greeter {
 constructor(
 @Component(LoggerService) private logger: LoggerService,
 private greeting: string,
 ) {}
}

const greeter = container.construct(Greeter, { 1: 'Hello from config' });
```

Called to initialize environment-specific configuration.

**Example:**

```typescript
@Container()
export class DatabaseService {
 setEnv(env: Record<string, any>) {
 console.log('DB URL:', env.DATABASE_URL);
 }
}

const db = container.resolve(DatabaseService);
db.setEnv(process.env);
```

Called to set execution context (e.g., request context).

**Example:**

```typescript
@Container()
export class RequestService {
 setCtx(context: any) {
 console.log('Context:', context);
 }
}

const service = container.resolve(RequestService);
service.setCtx({ userId: '123', requestId: 'abc' });
```

The DI container class.

```typescript
class Container {
 register<T>(serviceClass: new (...args: any[]) => T, options?: { singleton?: boolean }): void;
 registerFactory<T>(name: string, factory: () => T, options?: { singleton?: boolean }): void;
 resolve<T>(serviceClass: new (...args: any[]) => T | string): T;
 has(serviceClass: any): boolean;
 getServiceNames(): string[];
}
```

```typescript
import { Container } from '@di-framework/core/decorators';
import {
 Agent,
 AiService,
 configureAi,
 OpenAiChatModel,
 resolveAiService,
 resolveAnnotatedAgent,
 SystemMessageAnn,
 Tool,
 ToolParam,
 ToolSet,
 UserMessageAnn,
 WithMemory,
 MemoryId,
} from '@di-framework/ai';

@ToolSet()
@Container()
class WeatherTools {
 @Tool({
 description: 'Get weather for a city',
 inputSchema: {
 type: 'object',
 properties: { city: { type: 'string' } },
 required: ['city'],
 },
 })
 getWeather(@ToolParam('City name') input: { city: string }) {
 return { temp: 68, city: input.city };
 }
}

@AiService({ tools: [WeatherTools] })
@WithMemory()
class WeatherBot {
 @SystemMessageAnn('You help with weather questions.')
 ask(@UserMessageAnn() question: string, @MemoryId() sessionId: string): Promise<string> {
 throw new Error('handled by AiService proxy');
 }
}

@Agent({
 system: 'You help with weather.',
 tools: [WeatherTools],
})
class WeatherAgent {}

configureAi({
 chatModel: new OpenAiChatModel({ model: 'gpt-4o-mini' }),
 toolBeans: [WeatherTools],
});

const bot = resolveAiService(WeatherBot);
await bot.ask('Weather in Yorktown?', 'session-1');

const agent = resolveAnnotatedAgent(WeatherAgent);
await agent.chat('Weather in Yorktown?');
```

`configureAi` registers the chat model, a singleton `ChatClient`, a **prototype** `ChatClient.Builder`, optional memory/tools/advisors, and (by default) scans annotations so `@AiService` / `@Agent` classes become resolvable factories.

```typescript
import { Component, Container } from '@di-framework/core/decorators';
import {
 AiTokens,
 ChatAgent,
 type ChatClientBuilder,
 configureAi,
 OpenAiChatModel,
} from '@di-framework/ai';

configureAi({ chatModel: new OpenAiChatModel() });

@Container()
class SupportAgentService {
 private readonly agent: ChatAgent;

 constructor(@Component(AiTokens.CHAT_CLIENT_BUILDER) builder: ChatClientBuilder) {
 this.agent = ChatAgent.fromBuilder(builder)
 .system('You are an e-commerce support assistant.')
 .build();
 }

 chat(prompt: string, sessionId: string) {
 return this.agent.chat(prompt, { conversationId: sessionId });
 }
}
```

Each resolve of `AiTokens.CHAT_CLIENT_BUILDER` yields a fresh builder (Spring `@Scope("prototype")` style). Customize per service without mutating a shared client.

```typescript
import { ChatClient, OpenAiChatModel } from '@di-framework/ai';

const model = new OpenAiChatModel({ model: 'gpt-4o-mini' });
const client = ChatClient.create(model);

const answer = await client
 .prompt()
 .system('You are concise.')
 .user('What is Yorktown known for?')
 .call()
 .content();
```

Advisors, default tools, and default system text can be attached on the builder before `build()`, or per prompt.

```typescript
import { MessageWindowChatMemory, configureAi, WithMemory, MemoryId } from '@di-framework/ai';

configureAi({
 chatModel: /* … */,
 memory: new MessageWindowChatMemory({ maxMessages: 20 }),
});

@AiService()
@WithMemory()
class RememberingBot {
 talk(@UserMessageAnn() message: string, @MemoryId() sessionId: string): Promise<string> {
 throw new Error('proxy');
 }
}
```

`@MemoryId()` / `@ConversationId()` bind a method parameter to the chat-memory conversation id. Other advisor stereotypes: `@WithRag` / `@RetrievalAugmented`, `@WithTools`, `@AiObserved` / `@Observed`, plus `@AiAdvisor` / `@AdvisorOrder` for custom advisor beans.

- **`ChatAgent`** — multi-turn chat with tools/memory; build via `ChatAgent.create(...)`, `chatAgent(...)`, or `ChatAgent.fromBuilder(builder)`.
- **`@Agent` / `@ChatAgentBean`** — declarative bean resolved with `resolveAnnotatedAgent`.
- **Workflows** (imperative + stereotypes): `ChainWorkflow`, `RoutingWorkflow`, `ParallelizationWorkflow`, `OrchestratorWorkersWorkflow`, `EvaluatorOptimizerWorkflow`, with matching `@Chain`, `@Route` / `@Router`, `@Parallel`, `@Orchestrator` / `@Worker`, `@Evaluate` / `@Optimize`.
- **`GraphWorkflow`** — typed graph runtime for arbitrary control flow (linear, branch, loop, nested subgraphs). Fluent builder with async edge predicates/transforms, `AbortSignal`, `maxSteps`, build-time validation, and lifecycle hooks. Helpers: `chatToolLoopGraph`, `simpleAgentGraph`. Graph stereotypes are deferred until the imperative API is stable.
- **`PlannerExecutorWorkflow`** — plan → act → replan loop on `ChatClient` + tools, with step limits and cycle protection.
- **`A2ABus`** — thin in-process agent-to-agent message bus with optional human-in-the-loop hooks (local only; not a network protocol).

```typescript
import { GRAPH_FINISH, GRAPH_START, GraphWorkflow, PlannerExecutorWorkflow } from '@di-framework/ai';

const graph = GraphWorkflow.builder<number, string>('example')
 .node('double', (n) => n * 2)
 .node('label', (n) => `value=${n}`)
 .edge(GRAPH_START, 'double')
 .edge('double', 'label')
 .edge('label', GRAPH_FINISH)
 .build();

const { output, path } = await graph.run(21, { maxSteps: 50 });

const { answer } = await PlannerExecutorWorkflow.of(chatClient).run(goal, {
 tools: [tool],
 maxSteps: 6,
});
```

